var strength = new ArcPasswordStrength
{
    Value = password,
    Placeholder = "At least 8 characters"
};
strength.ValueChanged += (_, args) =>
{
    password = args.Value;
    passwordError = string.Empty;
};

var form = new StackPanel
{
    Spacing = 10,
    Children =
    {
        new TextBlock { Text = "Create your account", Classes = { "arc-heading" } },
        AppKit.Providers(provider => SignUp(provider)),
        AppKit.Input("Maya Chen", name, value => name = value),
        AppKit.Input("maya@northwind.co", email, value => email = value),
        AppKit.Field("Password", strength, "Use a phrase you can remember."),
        AppKit.Check("Email me product updates", updates, value => updates = value),
        AppKit.Btn("Create account", ArcButtonVariant.Primary, ArcButtonSize.Md, Submit, height: 42, stretch: true)
    }
};

return AppKit.Screen(AppKit.Card(form, 20, 20), 590);
